require "db.php";require "functions.php";need_role("student");$error="";$cats=["Facilities","Hostel","IT Support","Cleanliness","Safety","Academic","Other"];$priorities=["Low","Medium","High","Urgent"];
if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$title=trim($_POST["title"]??"");$cat=$_POST["category"]??"";$desc=trim($_POST["description"]??"");$loc=trim($_POST["location"]??"");$priority=$_POST["priority"]??"Medium";
 if($title===""||$desc==="")$error="Enter a title and describe the issue.";elseif(!in_array($cat,$cats,true)||!in_array($priority,$priorities,true))$error="Choose a valid category and priority.";
 else{$q=$pdo->prepare("INSERT INTO complaints(student_id,title,category,description,location,priority) VALUES(?,?,?,?,?,?)");$q->execute([(int)$_SESSION["user_id"],$title,$cat,$desc,$loc?:null,$priority]);flash("Your complaint has been submitted.");header("Location: my_complaints.php");exit;}
}
$title="Submit complaint";require "layout.php";?>
<div class="page-heading"><div><div class="eyebrow">MAKE YOUR VOICE HEARD</div><h1>Submit a <span class="green">complaint.</span></h1><p>Tell us what needs attention. Your report is private from other students.</p></div><a class="btn btn-outline" href="dashboard.php">← Dashboard</a></div>
<div class="content-grid form-grid"><section class="panel"><h2>Complaint details</h2><p class="muted">Fields marked with * are required.</p><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf_token" value="<?=e(csrf())?>"><label>Complaint title *</label><input name="title" maxlength="150" required placeholder="e.g. Wi-Fi not working in library"><div class="two-col"><div><label>Category *</label><select name="category"><?php foreach($cats as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div><div><label>Priority</label><select name="priority"><?php foreach($priorities as $v):?><option><?=e($v)?></option><?php endforeach;?></select></div></div><label>Campus location</label><input name="location" maxlength="150" placeholder="e.g. Main library, second floor"><label>Describe the issue *</label><textarea name="description" rows="6" required placeholder="What happened? When did you notice it?"></textarea><button class="btn btn-primary">Submit complaint ↗</button></form></section><aside class="panel soft"><div class="feature-icon">◈</div><h3>Report with confidence.</h3><p class="muted">Your complaint is linked to your account securely. Other students cannot view your reports.</p><hr><b>Private by default</b><p class="muted small">Your identity is hidden from staff in this starter interface and from other students. Admins can see identity to manage reports.</p></aside></div><?php require "end.php";?>
